// ServerInterface represents all server handlers.
type ServerInterface interface {
	// AcceptInvite Create an account from an invite
	// (POST /auth/invites/accept)
	AcceptInvite(w http.ResponseWriter, r *http.Request)
	// CheckInvite Check an invite token before signing up
	// (POST /auth/invites/check)
	CheckInvite(w http.ResponseWriter, r *http.Request)
	// Login Sign in with a username and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Sign out (session only)
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// BrowseCatalog Browse the catalogue
	// (GET /catalog/browse)
	BrowseCatalog(w http.ResponseWriter, r *http.Request, params BrowseCatalogParams)
	// GetCatalogEntry One catalogue entry in full
	// (GET /catalog/entries/{entry_id})
	GetCatalogEntry(w http.ResponseWriter, r *http.Request, entryId EntryId, params GetCatalogEntryParams)
	// GetCatalogEntryCover An entry's cover image
	// (GET /catalog/entries/{entry_id}/cover)
	GetCatalogEntryCover(w http.ResponseWriter, r *http.Request, entryId EntryId)
	// SearchCatalog Search the catalogue by title
	// (GET /catalog/search)
	SearchCatalog(w http.ResponseWriter, r *http.Request, params SearchCatalogParams)
	// ListInvites List open invites
	// (GET /invites)
	ListInvites(w http.ResponseWriter, r *http.Request)
	// CreateInvite Create an invite
	// (POST /invites)
	CreateInvite(w http.ResponseWriter, r *http.Request)
	// DeleteInvite Revoke an invite
	// (DELETE /invites/{id})
	DeleteInvite(w http.ResponseWriter, r *http.Request, id Id)
	// GetMe The signed-in user
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change your own profile
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ListMyApiKeys Your API keys (session only)
	// (GET /me/api-keys)
	ListMyApiKeys(w http.ResponseWriter, r *http.Request)
	// CreateMyApiKey Create an API key (session only)
	// (POST /me/api-keys)
	CreateMyApiKey(w http.ResponseWriter, r *http.Request)
	// DeleteMyApiKey Revoke an API key (session only)
	// (DELETE /me/api-keys/{id})
	DeleteMyApiKey(w http.ResponseWriter, r *http.Request, id Id)
	// ChangeMyPassword Change your own password (session only)
	// (POST /me/password)
	ChangeMyPassword(w http.ResponseWriter, r *http.Request)
	// ListMySessions Your signed-in sessions (session only)
	// (GET /me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// DeleteMySession Sign out another session (session only)
	// (DELETE /me/sessions/{id})
	DeleteMySession(w http.ResponseWriter, r *http.Request, id Id)
	// ListPlugins List source plugins
	// (GET /plugins)
	ListPlugins(w http.ResponseWriter, r *http.Request)
	// RegisterPlugin Add a source plugin running as a service
	// (POST /plugins)
	RegisterPlugin(w http.ResponseWriter, r *http.Request)
	// DeletePlugin Remove a plugin and its sources
	// (DELETE /plugins/{plugin_id})
	DeletePlugin(w http.ResponseWriter, r *http.Request, pluginId PluginId)
	// GetPlugin Get a plugin
	// (GET /plugins/{plugin_id})
	GetPlugin(w http.ResponseWriter, r *http.Request, pluginId PluginId)
	// UpdatePlugin Change a plugin's address or key, or turn it off
	// (PATCH /plugins/{plugin_id})
	UpdatePlugin(w http.ResponseWriter, r *http.Request, pluginId PluginId)
	// GetPluginConfig A plugin's configuration and its schema
	// (GET /plugins/{plugin_id}/config)
	GetPluginConfig(w http.ResponseWriter, r *http.Request, pluginId PluginId)
	// SetPluginConfig Replace a plugin's configuration
	// (PUT /plugins/{plugin_id}/config)
	SetPluginConfig(w http.ResponseWriter, r *http.Request, pluginId PluginId)
	// SyncPlugin Refresh a plugin's info, health and sources now
	// (POST /plugins/{plugin_id}/sync)
	SyncPlugin(w http.ResponseWriter, r *http.Request, pluginId PluginId)
	// GetSetup First-run wizard state
	// (GET /setup)
	GetSetup(w http.ResponseWriter, r *http.Request)
	// CreateSetupAdmin Create the first account (the admin)
	// (POST /setup/admin)
	CreateSetupAdmin(w http.ResponseWriter, r *http.Request)
	// CompleteSetup Finish the first-run wizard
	// (POST /setup/complete)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// ListSources Sources the caller may use
	// (GET /sources)
	ListSources(w http.ResponseWriter, r *http.Request, params ListSourcesParams)
	// UpdateSource Turn a source on or off for everyone
	// (PATCH /sources/{source_id})
	UpdateSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// SourceChapters A series' chapters exactly as the source lists them
	// (GET /sources/{source_id}/chapters)
	SourceChapters(w http.ResponseWriter, r *http.Request, sourceId SourceId, params SourceChaptersParams)
	// SourceFilters A source's search filters
	// (GET /sources/{source_id}/filters)
	SourceFilters(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// SourceImage An image from a source (covers, icons)
	// (GET /sources/{source_id}/image)
	SourceImage(w http.ResponseWriter, r *http.Request, sourceId SourceId, params SourceImageParams)
	// SourceLatest A source's latest updates
	// (GET /sources/{source_id}/latest)
	SourceLatest(w http.ResponseWriter, r *http.Request, sourceId SourceId, params SourceLatestParams)
	// SourcePopular A source's popular series
	// (GET /sources/{source_id}/popular)
	SourcePopular(w http.ResponseWriter, r *http.Request, sourceId SourceId, params SourcePopularParams)
	// SourceSearch Search a source
	// (POST /sources/{source_id}/search)
	SourceSearch(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// SourceSeries A series on a source, in full
	// (GET /sources/{source_id}/series)
	SourceSeries(w http.ResponseWriter, r *http.Request, sourceId SourceId, params SourceSeriesParams)
	// GetSystemHealth Detailed health (admins)
	// (GET /system/health)
	GetSystemHealth(w http.ResponseWriter, r *http.Request)
	// GetSystemInfo Server name, version and setup state
	// (GET /system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// GetMetaConnection The metadata service connection and its state
	// (GET /system/meta)
	GetMetaConnection(w http.ResponseWriter, r *http.Request)
	// SetMetaConnection Connect the metadata service
	// (PUT /system/meta)
	SetMetaConnection(w http.ResponseWriter, r *http.Request)
	// CheckMetaConnection Check the metadata service again now
	// (POST /system/meta/check)
	CheckMetaConnection(w http.ResponseWriter, r *http.Request)
	// RunMetaProviderSync Start a sync of a metadata provider
	// (POST /system/meta/providers/{provider}/sync)
	RunMetaProviderSync(w http.ResponseWriter, r *http.Request, provider string)
	// ListUsers List users
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request, params ListUsersParams)
	// CreateUser Create a user with a password
	// (POST /users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Delete a user
	// (DELETE /users/{id})
	DeleteUser(w http.ResponseWriter, r *http.Request, id Id)
	// GetUser Get a user
	// (GET /users/{id})
	GetUser(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateUser Change a user
	// (PATCH /users/{id})
	UpdateUser(w http.ResponseWriter, r *http.Request, id Id)
}

